from django.urls import path
from rest_framework_simplejwt.views import TokenRefreshView
from .views import RegisterView, LoginView, LogoutView, MeView, PasswordRecoveryView, PasswordResetView, PasswordRecoveryVerifyView, ChangePasswordView, ChangeEmailView
urlpatterns = [path('auth/register/', RegisterView.as_view()), path('auth/login/', LoginView.as_view()), path('auth/refresh/', TokenRefreshView.as_view()), path('auth/logout/', LogoutView.as_view()), path('auth/password-recovery/', PasswordRecoveryView.as_view()), path('auth/password-reset/', PasswordResetView.as_view()), path('users/me/', MeView.as_view()), path('users/me/change-password/', ChangePasswordView.as_view()), path('users/me/change-email/', ChangeEmailView.as_view()), path('auth/password-recovery/verify/', PasswordRecoveryVerifyView.as_view())]
